{
  "decision": "needs_more_evidence",
  "objections": [
    {
      "severity": "minor",
      "problem": "The claim states 'always stretch your body after waking up', but the study only measured effects of a single bout of stretching (4 min) in healthy recreationally fit individuals, not specifically after waking up.",
      "requested_action": "More evidence on timing of stretching relative to waking up is needed."
    },
    {
      "severity": "minor",
      "problem": "The claim mentions 'boost circulation', but the study measured [HHb] and [Hbtot ] changes, which are specific to muscle oxygenation and blood volume, not general circulation.",
      "requested_action": "More evidence on general circulation effects is needed."
    },
    {
      "severity": "minor",
      "problem": "The claim does not specify the duration of stretching (4 min vs. 'always'), and the study only tested a single bout, not habitual stretching.",
      "requested_action": "More evidence on habitual stretching routines is needed."
    }
  ],
  "remaining_gaps": [
    "No data on effects of stretching after waking up",
    "No data on general circulation vs. local muscle circulation",
    "No data on habitual stretching routines"
  ]
}
